package com.yuyutian.mytools.gateway.controller;
import com.yuyutian.mytools.gateway.config.GatewayProperties;import com.yuyutian.mytools.gateway.model.*;import com.yuyutian.mytools.gateway.model.MessagingGatewayModels.*;import com.yuyutian.mytools.gateway.service.*;import com.yuyutian.mytools.gateway.web.GatewayRequestFilter;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
class MessagingGatewayControllerTest {@Test void shouldInjectOwnerIntoMessageQuery(){MessagingGatewayClient client=mock(MessagingGatewayClient.class);MessagingGatewayController controller=new MessagingGatewayController(properties(),client);when(client.list(55L,null,50,"correlation")).thenReturn(new MessagePage(List.of(),null));assertThat(controller.list(null,50,request()).items()).isEmpty();verify(client).list(55L,null,50,"correlation");}
 private MockHttpServletRequest request(){MockHttpServletRequest request=new MockHttpServletRequest();request.setAttribute(GatewayRequestFilter.PRINCIPAL_ATTRIBUTE,new GatewayPrincipal(55L,"user",List.of("USER"),null));request.setAttribute(GatewayRequestFilter.CORRELATION_ATTRIBUTE,"correlation");return request;}
 private GatewayProperties properties(){return new GatewayProperties(GatewayProperties.IdentityMode.LEGACY,false,false,Set.of(),false,Set.of(),false,Set.of(),"http://mytools","http://identity","http://reader","http://drive","http://download","gateway-token","identity-token","reader-token","drive-token","download-token",1000,3000,false,"","",true,"http://messaging","messaging-token");}}
